css:
.log-body p { margin: 0 0 0.4em; }
.log-body p:last-child { margin-bottom: 0; }
.log-body ul, .log-body ol { margin: 0.3em 0; padding-left: 1.5em; }
.log-body pre { margin: 0.3em 0; white-space: pre-wrap; font-size: 0.9em; }
.log-mention { font-weight: 600; color: var(--log-accent); }
.log-audio { color: var(--log-muted); font-size: 0.9em; }
.pb { height: 0; }
.cu-text { margin: 0; white-space: pre-wrap; }
.log-page, .log-flow { background-color: var(--log-sheet); }
.log-node--message { margin: 0 0 calc(var(--log-gap, 0.7) * 1em); }
.log-node--message.log-merged { margin-top: calc(var(--log-gap, 0.7) * -0.55em); }
.dz-body, .dz-note-body, .pro-b, .qt-b, .cv-title, .cv-sub, .dz-scene-body { font-family: var(--log-face); }
.dz-kind, .dz-time, .dz-form, .dz-sys, .dz-note-tag, .dz-scene-tag, .hd, .tr, .ip-tag, .qt-tag, .pro-h, .toc, .cv-tab, .cv-k, .cv-stamp, .ph, .pf, .cu-title { font-family: "Courier New", "SFMono-Regular", "Noto Sans Mono CJK SC", monospace; }
.dz { display: grid; grid-template-columns: calc(var(--log-photo, 2.6) * 1em) 1fr; column-gap: 0.8em; color: var(--log-ink); }
.dz .dz-ph, .dz .dz-photo { grid-column: 1; grid-row: 1 / span 2; width: calc(var(--log-photo, 2.6) * 1em); height: calc(var(--log-photo, 2.6) * 1.25em); margin-top: 0.15em; }
.dz .dz-ph { display: flex; align-items: center; justify-content: center; border: 1px dashed var(--log-rule); text-align: center; font-size: 0.6em; width: calc(var(--log-photo, 2.6) * 1em / 0.6); height: calc(var(--log-photo, 2.6) * 1.25em / 0.6); line-height: 1.3; color: var(--log-muted); }
.dz .dz-photo { max-height: none; max-width: none; padding: 2px; border: 1px solid var(--log-ink); background: #ffffff; object-fit: cover; }
:root[data-log-showavatar="false"] .dz { grid-template-columns: 1fr; }
:root[data-log-showavatar="false"] .dz-ph, :root[data-log-showavatar="false"] .dz-photo { display: none; }
:root[data-log-showavatar="false"] .dz-head, :root[data-log-showavatar="false"] .dz-body, :root[data-log-showavatar="false"] .log-continued .dz::before { grid-column: 1; }
.dz-head { grid-column: 2; grid-row: 1; display: flex; flex-wrap: wrap; align-items: baseline; gap: 0.1em 0.7em; padding-bottom: 0.15em; border-bottom: 1px solid var(--log-ink); line-height: 1.4; }
.dz-kind { padding: 0 0.35em; border: 1px solid var(--log-accent); font-size: 0.68em; letter-spacing: 0.2em; color: var(--log-accent); }
.dz-name { font-weight: 700; letter-spacing: 0.05em; color: var(--log-speaker-color, var(--log-ink)); }
.dz-time { margin-left: auto; font-size: 0.72em; color: var(--log-muted); }
:root[data-log-showtime="false"] .dz-time { display: none; }
.dz-body { grid-column: 2; grid-row: 2; min-width: 0; padding-top: 0.3em; line-height: 1.75; text-align: justify; }
.log-merged .dz-ph, .log-merged .dz-photo, .log-merged .dz-head { display: none; }
.log-merged .dz-body { padding-top: 0; }
.log-continued .dz::before { content: "（续上页）"; grid-column: 2; grid-row: 1; font-family: "Courier New", "SFMono-Regular", "Noto Sans Mono CJK SC", monospace; font-size: 0.7em; color: var(--log-muted); }
.dz-body img { display: block; max-height: 14em; margin: 0.4em 0; padding: 0.35em 0.35em 1.1em; border: 1px solid var(--log-rule); background: #ffffff; box-shadow: 1px 2px 0 rgba(0, 0, 0, 0.08); }
.dz-note { margin: 0.1em 0 0 calc(var(--log-photo, 2.6) * 1em + 0.8em); padding: 0.1em 0 0.1em 0.7em; border-left: 2px solid var(--log-accent); font-family: "Kaiti SC", "STKaiti", "KaiTi", "AR PL UKai CN", "Noto Serif CJK SC", serif; font-size: 0.92em; line-height: 1.6; color: var(--log-accent); }
.dz-note-tag { margin-right: 0.5em; padding: 0 0.3em; border: 1px solid var(--log-accent); font-size: 0.7em; letter-spacing: 0.15em; }
.dz-note-name { font-weight: 700; }
.dz-note-name::after { content: "："; }
.log-merged .dz-note-tag, .log-merged .dz-note-name { display: none; }
.dz-form { display: grid; grid-template-columns: 7em 1fr; margin-left: calc(var(--log-photo, 2.6) * 1em + 0.8em); border: 1px solid var(--log-ink); font-size: 0.85em; line-height: 1.5; color: var(--log-ink); break-inside: avoid; }
.dz-form-k { grid-column: 1; grid-row: 1; padding: 0.3em 0.5em; border-right: 1px solid var(--log-ink); background: rgba(0, 0, 0, 0.05); }
.dz-form-kind { display: block; font-size: 0.8em; letter-spacing: 0.3em; color: var(--log-accent); }
.dz-form-who { display: block; font-weight: 700; overflow-wrap: anywhere; }
.dz-form-v { grid-column: 2; grid-row: 1; padding: 0.3em 0.6em; min-width: 0; }
.dz-sys { margin-left: calc(var(--log-photo, 2.6) * 1em + 0.8em); padding: 0.35em 0.6em; border: 1px dashed var(--log-rule); font-size: 0.8em; line-height: 1.5; color: var(--log-muted); }
.dz-sys-tag { margin-right: 0.5em; letter-spacing: 0.2em; color: var(--log-ink); }
.dz-sys-name { font-weight: 700; }
.dz-sys-name::after { content: " ——"; font-weight: 400; }
.log-merged .dz-sys-tag, .log-merged .dz-sys-name { display: none; }
.dz-scene { margin-left: calc(var(--log-photo, 2.6) * 1em + 0.8em); color: var(--log-ink); }
.dz-scene-tag { display: inline-block; margin-bottom: 0.2em; padding: 0 0.4em; background: var(--log-ink); font-size: 0.68em; letter-spacing: 0.25em; color: var(--log-sheet); }
.dz-scene-body { line-height: 1.75; }
.hd { display: flex; align-items: baseline; gap: 0.5em; margin: 1.6em 0 0.9em; padding-bottom: 0.2em; border-bottom: 1px solid var(--log-ink); font-size: 1.1em; letter-spacing: 0.08em; color: var(--log-ink); break-after: avoid; }
.hd-mark { color: var(--log-accent); }
[data-log-level="1"] .hd { margin-top: 2em; padding: 0.3em 0.6em; border: 0; background: var(--log-ink); font-size: 1.2em; color: var(--log-sheet); }
[data-log-level="1"] .hd-mark { color: var(--log-sheet); }
[data-log-level="3"] .hd { border-bottom-style: dashed; font-size: 0.95em; }
.tr { margin: 1.2em 0; text-align: var(--log-style-align, center); font-size: 0.8em; letter-spacing: 0.2em; color: var(--log-muted); background: linear-gradient(var(--log-rule), var(--log-rule)) center / 100% 1px no-repeat; }
.tr-label { padding: 0.1em 0.8em; border: 1px dashed var(--log-muted); background: var(--log-sheet); }
.qt { margin: 1em 0 1em calc(var(--log-photo, 2.6) * 1em + 0.8em); padding: 0.5em 0.8em; border: 1px solid var(--log-rule); background: rgba(255, 255, 255, 0.45); text-align: var(--log-style-align, left); color: var(--log-ink); break-inside: avoid; }
.qt-tag { margin-bottom: 0.3em; font-size: 0.68em; letter-spacing: 0.3em; color: var(--log-accent); }
.log-style-italic .qt-b { font-style: italic; }
.pro { margin: 0 0 1.4em; border: 1px solid var(--log-ink); }
.pro-h { margin: 0; padding: 0.2em 0.6em; border-bottom: 1px solid var(--log-ink); font-size: 0.8em; font-weight: 700; letter-spacing: 0.3em; color: var(--log-ink); }
.pro-b { padding: 0.6em 0.8em; line-height: 1.75; color: var(--log-ink); }
.cv { position: relative; min-height: calc(var(--log-content-height, 180mm) * 0.92); display: flex; flex-direction: column; justify-content: center; break-after: page; }
.cv-tab { align-self: flex-start; padding: 0.3em 1.2em; border: 2px solid var(--log-ink); border-bottom: 0; font-size: 0.8em; letter-spacing: 0.25em; color: var(--log-ink); }
.cv-box { border: 2px solid var(--log-ink); }
.cv-row { display: grid; grid-template-columns: 5.5em 1fr; border-bottom: 1px solid var(--log-ink); }
.cv-row:last-child { border-bottom: 0; }
.cv-k { padding: 0.6em 0.6em; border-right: 1px solid var(--log-ink); font-size: 0.75em; letter-spacing: 0.15em; color: var(--log-muted); }
.cv-title { margin: 0; padding: 0.4em 0.6em; font-size: 1.6em; line-height: 1.35; color: var(--log-ink); }
.cv-sub { margin: 0; padding: 0.6em 0.6em; color: var(--log-ink); }
.cv-fig { margin: 1.4em 0 0; text-align: center; }
.cv-fig img { max-height: calc(var(--log-content-height, 180mm) * 0.4); padding: 0.4em 0.4em 1.4em; border: 1px solid var(--log-rule); background: #ffffff; }
.cv-stamp { position: absolute; top: 12%; right: 4%; padding: 0.1em 0.6em; border: 3px double var(--log-accent); font-size: 1.5em; font-weight: 700; letter-spacing: 0.4em; color: var(--log-accent); opacity: 0.85; }
.ip { margin: 1.2em auto; width: fit-content; max-width: 100%; padding: 0.5em 0.5em 0.4em; border: 1px solid var(--log-rule); background: #ffffff; box-shadow: 2px 3px 0 rgba(0, 0, 0, 0.08); break-inside: avoid; }
.ip-tag { margin-bottom: 0.35em; font-size: 0.68em; letter-spacing: 0.35em; color: var(--log-accent); }
.ip img { display: block; }
.ip figcaption { margin-top: 0.4em; font-family: "Kaiti SC", "STKaiti", "KaiTi", "AR PL UKai CN", "Noto Serif CJK SC", serif; font-size: 0.88em; color: var(--log-ink); }
.toc { break-after: page; }
.toc-h { margin: 0 0 0.8em; padding-bottom: 0.2em; border-bottom: 2px solid var(--log-ink); font-size: 1.15em; letter-spacing: 0.3em; }
.toc .log-toc-item { padding: 0.25em 0; border-bottom: 1px dashed var(--log-rule); font-size: 0.9em; }
.cu { margin: 1em 0; border: 1px solid var(--log-ink); background: repeating-linear-gradient(transparent 0, transparent 1.55em, var(--log-rule) 1.55em, var(--log-rule) 1.6em); break-inside: avoid; }
.log-style-accent .cu { border: 2px solid var(--log-accent); }
.cu-title { padding: 0.2em 0.6em; border-bottom: 1px solid var(--log-ink); background: var(--log-sheet); font-size: 0.8em; font-weight: 700; letter-spacing: 0.2em; }
.cu-text { padding: 0.3em 0.7em; font-family: var(--log-face); line-height: 1.6em; }
.cu-note { margin: 0; padding: 0 0.7em 0.3em; font-family: "Kaiti SC", "STKaiti", "KaiTi", "AR PL UKai CN", "Noto Serif CJK SC", serif; font-size: 0.85em; color: var(--log-accent); }
.ph { width: 100%; display: flex; align-items: center; gap: 1em; letter-spacing: 0.15em; }
.ph-title { flex: 1; text-align: center; }
.ph-r { padding: 0 0.4em; border: 1px solid var(--log-accent); color: var(--log-accent); }
.pf { width: 100%; display: flex; justify-content: space-between; gap: 1em; }
.pf-num::before { content: "第 "; }
.pf-num::after { content: " 页"; }
@media print {
  .dz-body img, .ip, .cv-fig img { box-shadow: none; }
}
